        "データと根拠の残し方::専任系は窓口を一本化しやすい一方で、仲介会社の販売力と報告品質が成果を左右します。一般媒介は幅広く声をかけやすい反面、同じ買主への重複提案、価格情報の拡散、古い資料の流通が起きやすくなります。契約形態を選ぶ前に、秘匿性、販売期間、買主候補の広さ、社内対応力を確認します。",
