        "DD範囲を決める::対象物件の用途、規模、スケジュール、投資判断の重要度に応じてDD範囲を決めます。買付前の初期DDと契約前の本格DDを分けると、スピードと精度のバランスを取りやすくなります。",
        "資料請求を管理する::登記、契約書、レントロール、修繕履歴、建築確認、検査済証、図面、PMレポート、点検記録、環境資料を請求します。資料の受領日、最新版、未提出、確認担当を管理します。",
        "専門家確認を進める::法務は権利や契約、物理は建物や設備、経済は収益と費用、環境は土壌やアスベスト、テナントは賃貸借条件を見ます。専門家コメントは要約だけでなく、原文リンクや根拠資料と紐づけます。",
        "Q&Aと論点を整理する::売主、仲介会社、専門家への質問を一覧化します。未回答、回答済み、追加確認、価格影響あり、契約条項反映済みなど、ステータス管理をします。",
        "価格と契約条件へ反映する::DDで見つかったリスクは、価格調整、表明保証、前提条件、解除条件、引渡し条件へ反映します。投資委員会や稟議では、リスクを発見したことより、どう扱うかを説明することが重要です。",
