        "データと根拠の残し方::法務DDでは登記、権利、契約、許認可、境界、越境を確認します。物理DDでは建物、設備、劣化、修繕、遵法性を見ます。経済DDではレントロール、NOI、運営費、滞納、CAPEXを確認します。環境DDでは土壌汚染、アスベスト、地下埋設物など、テナントDDでは賃貸借契約、解約リスク、敷金、原状回復を確認します。",
        "不動産テックの使いどころ::不動産テックを使う場合は、資料請求、提出状況、Q&A、専門家コメント、契約反映状況を一つの論点表で管理します。資料フォルダだけでは、誰が何を確認し、どのリスクが残っているか分かりにくくなります。期限、担当者、重要度、価格影響、契約反映先を項目化します。",
        "よくある詰まりどころ::よくある失敗は、DDでリスクを見つけた後の処理が曖昧なことです。是正を求めるのか、価格で調整するのか、特約で容認するのか、撤退するのかを決めなければ、DDは投資判断に役立ちません。DD終了前に、未解決論点と意思決定者の承認状況を必ず確認します。",
