      "body": [
        "掲載項目を決める::所在地、交通、土地・建物面積、用途地域、建ぺい率、容積率、価格、権利関係、現況、引渡条件、収益物件であれば賃料、稼働率、レントロール概要などを整理します。事業用不動産では、検討初期に必要な情報が住宅より多くなるため、アセットタイプごとにテンプレートを分けると作りやすくなります。",
        "根拠資料と照合する::登記、公図、測量図、確認済証、検査済証、賃貸借契約、固定資産税資料、現地写真と照合します。古い図面や過去の募集資料を流用する場合は、面積、価格、法令制限、取引態様、現況が最新かを確認します。",
        "買主目線で編集する::買主が最初に知りたいのは、価格、立地、面積、収益性、リスク、次に見るべき資料です。魅力だけを強調するより、検討上の前提や確認中事項も整理した方が、法人買主との後続コミュニケーションが進めやすくなります。",
        "広告表示を確認する::一般消費者に提示する広告やWeb掲載では、不動産広告の表示規約や宅建業法上の表示事項に注意します。業者間資料であっても、外部に出る可能性がある資料は、誤認を招く表現や根拠の薄い訴求を避けます。",
        "更新履歴を管理する::価格変更、賃料更新、空室状況、写真差し替え、特記事項追加があった場合、版数と更新日を残します。複数の仲介会社や買主候補に資料を配る場合、古い版が残ると説明の食い違いにつながります。",
        "実務の勘所::物件概要書は、買主が初期判断をするための入口資料です。所在地、交通、価格、土地建物面積、権利、法令制限、収益、写真、地図、特記事項をただ並べるのではなく、買主が次に何を確認すべきか分かる構成にします。事業用不動産では、住宅よりも用途、収益、遵法性、テナント条件の比重が大きくなります。",
        "データと根拠の残し方::根拠資料との照合は欠かせません。登記、公図、測量図、確認済証、検査済証、固定資産税資料、賃貸借契約、レントロール、現地写真を確認し、資料に載せる数値の出典を残します。不動産広告では表示規約や宅建業法上の取引態様、広告開始時期、誤認表示にも注意が必要です。",
        "不動産テックの使いどころ::不動産テックを使う場合は、案件データから物件概要書へ自動反映できる項目と、人が確認すべき項目を分けます。写真、地図、VR、図面作成ツールは訴求力を高めますが、面積、権利、法令制限、価格、収益の正確性は別途チェックが必要です。",
        "よくある詰まりどころ::失敗しやすいのは、魅力を強調するあまり、確認中事項や制約条件が見えなくなることです。法人買主は、良い点だけでなく検討上のリスクも早く知りたいと考えます。版数、更新日、配布先、変更履歴を残し、古い資料が流通しないよう管理します。",
        "社内運用に落とすときのポイント::この記事の業務は、担当者の経験だけで処理すると品質がばらつきやすい領域です。案件ごとに、確認した資料、判断した理由、未確認の論点、次に確認する相手を残しておくと、担当変更や上長レビュー、買主からの質問対応でも説明しやすくなります。とくに法人取引では、現場担当、管理職、法務、財務、外部専門家が同じ前提を見られる状態を作ることが重要です。",
        "更新とレビューのタイミング::最初に作った資料や判断は、査定、媒介契約、DD、買付、契約交渉の過程で変わります。新しい資料を取得したとき、価格や条件が変わったとき、買主から重要な質問が出たとき、専門家コメントが戻ったときには、案件メモと関連資料を更新します。更新日、更新者、変更理由を残すことで、古い情報を前提にした説明や社内承認を防ぎやすくなります。"
      ],
