      "body": [
        "建物状態を把握する::外壁、防水、給排水、電気、空調、昇降機、消防設備、共用部、室内設備などを確認します。法定点検や現地確認の結果を、写真や指摘事項と一緒に残します。",
        "修繕履歴を整理する::過去の工事内容、発注先、金額、保証、写真、完了日を整理します。修繕履歴がないと、次に必要な工事や売却時の説明が難しくなります。",
        "中長期計画を作る::工事項目、実施時期、概算費用、優先順位を置きます。マンションの長期修繕計画や賃貸住宅の計画修繕の考え方を参考にしつつ、保有方針や出口戦略に合わせて調整します。",
        "予算とNOI影響を見る::修繕費、CAPEX、賃料改善、空室抑制、売却価格への影響を見ます。単年度の費用だけで判断せず、保有期間全体のNOIと出口価格への影響を確認します。",
        "実施後に履歴を更新する::工事完了後は、見積、発注、写真、保証書、完了報告を保存します。履歴を更新しておくと、PM/BMレポート、DD、売却資料作成に活用できます。",
        "実務の勘所::修繕計画では、建物状態、修繕履歴、中長期計画、予算、NOI影響を一体で見ます。国土交通省の長期修繕計画ガイドラインは、マンションの計画修繕を考えるうえで参考になりますが、収益不動産では保有方針、売却予定、テナント影響、CAPEXの回収可能性も合わせて判断します。",
        "データと根拠の残し方::対象は、外壁、防水、給排水、電気、空調、昇降機、消防設備、共用部、室内設備、駐車場、外構などです。法定点検、現地報告、見積、写真、保証書、完了報告を履歴として残すと、次の工事判断や売却時のDDで説明しやすくなります。",
        "不動産テックの使いどころ::不動産テックは、点検指摘、修繕依頼、見積、発注、写真、完了報告を一元管理する用途に向いています。PM/BM、所有者、会計が同じ履歴を見られるようにすると、突発修繕と計画修繕を分け、CAPEXと修繕費の扱いも整理しやすくなります。",
        "よくある詰まりどころ::失敗しやすいのは、短期費用を抑えるために修繕を先送りし、結果として空室、賃料下落、突発工事、売却時の価格調整を招くことです。単年度予算だけでなく、保有期間全体のNOIと出口価格への影響を見て、実施時期と優先順位を決めます。",
        "社内運用に落とすときのポイント::この記事の業務は、担当者の経験だけで処理すると品質がばらつきやすい領域です。案件ごとに、確認した資料、判断した理由、未確認の論点、次に確認する相手を残しておくと、担当変更や上長レビュー、買主からの質問対応でも説明しやすくなります。とくに法人取引では、現場担当、管理職、法務、財務、外部専門家が同じ前提を見られる状態を作ることが重要です。",
        "更新とレビューのタイミング::最初に作った資料や判断は、査定、媒介契約、DD、買付、契約交渉の過程で変わります。新しい資料を取得したとき、価格や条件が変わったとき、買主から重要な質問が出たとき、専門家コメントが戻ったときには、案件メモと関連資料を更新します。更新日、更新者、変更理由を残すことで、古い情報を前提にした説明や社内承認を防ぎやすくなります。",
        "投資判断とのつなげ方::修繕の優先順位は、緊急度だけでなく、稼働率、賃料維持、テナント満足、保険、法定点検、売却時の説明力を合わせて決めます。短期保有なら売却前に説明が必要な工事を優先し、長期保有なら予防保全と資産価値維持を重視します。工事を実施しない判断をした場合も、理由と再確認時期を残しておくと、後のDDや社内監査で説明しやすくなります。"
      ],
