      "title": "4号特例縮小後の中古戸建調査：売買仲介で確認を前倒しする",
      "process": "不動産仲介",
      "task": "物件調査",
      "lead": "2025年4月以降は、木造2階建てなどの中古戸建でも再建築や大規模リフォームの説明に必要な確認が増えています。物件調査の早い段階で、確認申請、検査済証、現況差異を押さえます。",
      "message": "4号特例の縮小は設計者や工務店だけの話ではなく、中古戸建の仲介実務にも影響します。買主が購入後に増改築や建て替えを想定するほど、確認申請の対象か、検査済証があるか、現況と図面にズレがないか、既存不適格の可能性があるかを早めに整理しておく必要があります。",
